<?php
/**
 * One Christian Church theme setup.
 *
 * The pages are ordinary block-editor content. Activating the theme writes the design into them (inc/content.php)
 * and switching to another theme puts the site's previous pages back. The header menu, promo strip and button are
 * menus and Customizer settings (inc/site-parts.php), the footer is a synced pattern, the forms email the church
 * (inc/forms.php) and the header search is rebuilt from the live pages (inc/search.php).
 *
 * @package One_Christian_Church
 */

defined( 'ABSPATH' ) || exit;

/**
 * Settings generated by build.py: pages, menus, header defaults, forms, meta descriptions, videos, font URL.
 *
 * @return array
 */
function occ_data() {
	static $data = null;
	if ( null === $data ) {
		$data = json_decode( file_get_contents( get_theme_file_path( 'inc/theme-data.json' ) ), true );
	}
	return $data;
}

/**
 * Markup the shortcodes print (icons, 3D logos, waves...), generated by build.py.
 *
 * @return array
 */
function occ_fragments() {
	static $data = null;
	if ( null === $data ) {
		$data = json_decode( file_get_contents( get_theme_file_path( 'inc/fragments.json' ) ), true );
	}
	return $data;
}

require get_theme_file_path( 'inc/shortcodes.php' );
require get_theme_file_path( 'inc/site-parts.php' );
require get_theme_file_path( 'inc/content.php' );
require get_theme_file_path( 'inc/forms.php' );
require get_theme_file_path( 'inc/search.php' );
require get_theme_file_path( 'inc/admin.php' );

add_action(
	'after_setup_theme',
	function () {
		add_theme_support( 'title-tag' );
		add_theme_support( 'custom-logo', array( 'flex-width' => true, 'flex-height' => true ) );
		add_theme_support( 'html5', array( 'script', 'style', 'navigation-widgets', 'search-form' ) );
		// The theme's stylesheet does all the spacing, so WordPress's own layout rules stay out of the way.
		add_theme_support( 'disable-layout-styles' );
		add_theme_support( 'editor-styles' );
		add_editor_style( array( 'assets/css/style.css', 'assets/css/editor.css' ) );
		register_nav_menus(
			array(
				'primary' => __( 'Main menu (header)', 'one-christian-church' ),
				'search'  => __( 'Search shortcuts (shown when search opens)', 'one-christian-church' ),
			)
		);
	}
);

// A classic theme gets an extra wrapper inside every Group block; the design's CSS expects the blocks directly inside.
remove_filter( 'render_block_core/group', 'wp_restore_group_inner_container', 10 );

// The design pages are block content: keep them in the block editor even if a plugin such as Classic Editor turns it off.
add_filter(
	'use_block_editor_for_post',
	function ( $use, $post ) {
		return ( get_post_meta( $post->ID, '_occ_key', true ) || occ_footer_block_id() === $post->ID ) ? true : $use;
	},
	200,
	2
);

// Elementor puts an "Edit with Elementor" button in the block editor. On the design pages it would open the page's old
// Elementor version and replace the design when saved, so the button is left off there.
add_action(
	'enqueue_block_editor_assets',
	function () {
		$id = (int) get_the_ID();
		if ( $id && ( get_post_meta( $id, '_occ_key', true ) || occ_footer_block_id() === $id ) ) {
			wp_dequeue_script( 'elementor-gutenberg' );
		}
	},
	100
);

add_action(
	'wp_enqueue_scripts',
	function () {
		$version = occ_data()['version'];
		wp_enqueue_style( 'occ-fonts', occ_data()['fonts'], array(), null );
		wp_enqueue_style( 'occ-style', get_theme_file_uri( 'assets/css/style.css' ), array( 'occ-fonts' ), $version );
		wp_enqueue_script( 'occ-main', get_theme_file_uri( 'assets/js/main.js' ), array(), $version, array( 'strategy' => 'defer', 'in_footer' => true ) );
	}
);

// The design's fonts inside the block editor too.
add_action(
	'enqueue_block_assets',
	function () {
		if ( is_admin() ) {
			wp_enqueue_style( 'occ-fonts', occ_data()['fonts'], array(), null );
		}
	}
);

// A page's Excerpt (in the editor's sidebar) is its description for search engines; the theme has one for each of its pages.
add_action(
	'init',
	function () {
		add_post_type_support( 'page', 'excerpt' );
	}
);

add_action(
	'wp_head',
	function () {
		$seo_plugin = defined( 'WPSEO_VERSION' ) || defined( 'RANK_MATH_VERSION' ) || defined( 'AIOSEO_VERSION' ) || defined( 'SEOPRESS_VERSION' );
		$key        = is_front_page() ? 'home' : ( is_page() ? get_post_field( 'post_name', get_queried_object_id() ) : '' );
		$excerpt    = is_singular() ? get_post_field( 'post_excerpt', get_queried_object_id() ) : '';
		$desc       = $excerpt ? $excerpt : ( occ_data()['descriptions'][ $key ] ?? '' );
		if ( $desc && ! $seo_plugin ) {
			printf( '<meta name="description" content="%s">' . "\n", esc_attr( wp_strip_all_tags( $desc ) ) );
		}
		if ( ! has_site_icon() ) {
			printf( '<link rel="icon" href="%s" type="image/svg+xml">' . "\n", esc_url( get_theme_file_uri( 'assets/img/favicon.svg' ) ) );
		}
	}
);

/**
 * URL of one of the site's pages, found by slug so it works with any permalink setting.
 *
 * @param string $slug   Page slug, or 'home'.
 * @param string $anchor Optional fragment without '#'.
 * @return string
 */
function occ_url( $slug, $anchor = '' ) {
	if ( 'home' === $slug ) {
		$url = home_url( '/' );
	} else {
		$page = get_page_by_path( $slug );
		$url  = $page ? get_permalink( $page ) : home_url( '/' . $slug . '/' );
	}
	return $anchor ? $url . '#' . $anchor : $url;
}

/**
 * Turn a link setting into a URL: a page slug (optionally with #anchor) or a full address.
 *
 * @param string $value Slug, slug#anchor, #anchor or URL.
 * @return string
 */
function occ_link( $value ) {
	$value = trim( (string) $value );
	if ( '' === $value || preg_match( '~^(https?:|mailto:|tel:|sms:|/|#)~', $value ) ) {
		return $value;
	}
	list( $slug, $anchor ) = array_pad( explode( '#', $value, 2 ), 2, '' );
	return occ_url( $slug, $anchor );
}

/**
 * Links for the header search, slug => URL. Index entries built by WordPress also carry their own URL.
 *
 * @return array
 */
function occ_search_pages() {
	$pages = array( 'home' => occ_url( 'home' ) );
	foreach ( occ_data()['pages'] as $page ) {
		$pages[ $page['slug'] ] = occ_url( $page['slug'] );
	}
	return $pages;
}

/**
 * The church logo: the Site Identity logo when one is set, otherwise the theme's vector copy of it.
 *
 * @return string
 */
function occ_logo_html() {
	$id = get_theme_mod( 'custom_logo' );
	if ( $id ) {
		return wp_get_attachment_image( $id, 'medium', false, array( 'class' => 'logo-img', 'alt' => '' ) );
	}
	return occ_fragments()['mark'];
}

/**
 * Print the church logo.
 */
function occ_logo() {
	echo occ_logo_html(); // phpcs:ignore WordPress.Security.EscapeOutput -- the theme's own SVG or wp_get_attachment_image().
}

/**
 * A muted, looping background video for a slot. main.js starts it when it scrolls into view.
 *
 * @param string $slot  Key from theme-data.json "videos".
 * @param bool   $eager True for hero videos that should start loading right away.
 * @return string
 */
function occ_video_html( $slot, $eager = false ) {
	$src = occ_video_src( $slot );
	if ( ! $src ) {
		return '';
	}
	return sprintf(
		'<video class="bg-video" data-slot="%1$s" muted loop playsinline preload="%2$s"%3$s aria-hidden="true"><source %4$s="%5$s" type="video/mp4"></video>',
		esc_attr( $slot ),
		$eager ? 'auto' : 'metadata',
		$eager ? ' data-loaded="1"' : '',
		$eager ? 'src' : 'data-src',
		esc_url( $src )
	);
}

/**
 * Print a background video (used by the 404 template).
 *
 * @param string $slot  Video slot.
 * @param bool   $eager Start loading right away.
 */
function occ_video( $slot, $eager = false ) {
	echo occ_video_html( $slot, $eager ); // phpcs:ignore WordPress.Security.EscapeOutput -- escaped in occ_video_html().
}

/**
 * URL of a background video slot: a Customizer URL wins; otherwise assets/video/{slot}.mp4 if it was added to the theme.
 * With neither, it is empty and the animated colour background shows.
 *
 * @param string $slot Video slot.
 * @return string
 */
function occ_video_src( $slot ) {
	if ( empty( occ_data()['videos'][ $slot ] ) ) {
		return '';
	}
	$src = get_theme_mod( 'occ_video_' . $slot );
	if ( ! $src && file_exists( get_theme_file_path( 'assets/video/' . $slot . '.mp4' ) ) ) {
		$src = get_theme_file_uri( 'assets/video/' . $slot . '.mp4' );
	}
	return (string) $src;
}

/**
 * Print the clips every video spot cycles through. A slot that only reuses another slot's clip is skipped
 * unless a video of its own was set in the Customizer.
 */
function occ_video_list() {
	$urls = array();
	foreach ( array_keys( occ_data()['videos'] ) as $slot ) {
		if ( ! in_array( $slot, occ_data()['playlist'], true ) && ! get_theme_mod( 'occ_video_' . $slot ) ) {
			continue;
		}
		$src = occ_video_src( $slot );
		if ( $src && ! in_array( $src, $urls, true ) ) {
			$urls[] = esc_url_raw( $src );
		}
	}
	printf( '<script type="application/json" id="occ-videos">%s</script>' . "\n", wp_json_encode( $urls ) );
}
